const now = new Date();
const isSha256 = (value) => /^[a-f0-9]{64}$/.test(String(value || '').trim());
const manifestSha = String($env.VIRYAOS_WORKFLOW_MANIFEST_SHA || '9a4e58807417fc3504bbecd9c2b9d983fdcce7bbd26798e120229f9223df6ff1').trim();
if (!isSha256(manifestSha)) throw new Error('VIRYAOS_WORKFLOW_MANIFEST_SHA must be lowercase sha256');

const caps = [
  'fan.lifecycle.message',
  'booking.outreach',
  'outreach.send',
  'opportunity.application',
  'funding.submit',
  'ops.alert',
  'outreach.discovery',
];
if (String($env.VIRYAOS_ENABLE_TEAM_OPS || '0') === '1') caps.push('merch.reorder', 'merch.bundle', 'content.artifact', 'show.escalation');
if (String($env.VIRYAOS_ENABLE_FUNDING_PACKAGE || '0') === '1') caps.push('funding.package');
if (String($env.VIRYAOS_ENABLE_CALENDAR || '0') === '1') caps.push('calendar.upsert');

const metadata = {
  runtime: 'n8n',
  receipt_spooler: 'VOSRECEIPT00001',
  team_ops_gate: String($env.VIRYAOS_ENABLE_TEAM_OPS || '0'),
  team_email_gate: String($env.VIRYAOS_ENABLE_TEAM_EMAIL || '0'),
};

// team.email is fail-closed: desired state alone must never poison the whole
// executor heartbeat. Advertise it only when the exact secretless workflow
// attestation is fresh and bound to this manifest SHA.
const teamEmailDesired = String($env.VIRYAOS_ENABLE_TEAM_EMAIL || '0') === '1';
const attestationSha = String($env.VIRYAOS_WORKFLOW_ATTESTATION_SHA || '').trim();
const attestationManifestSha = String($env.VIRYAOS_WORKFLOW_ATTESTATION_MANIFEST_SHA || '').trim();
const attestedAtRaw = String($env.VIRYAOS_WORKFLOW_ATTESTED_AT || '').trim();
const attestedAtMs = Date.parse(attestedAtRaw);
const maxAttestationAgeMs = 14 * 24 * 60 * 60 * 1000;
const maxFutureSkewMs = 5 * 60 * 1000;
const attestationFresh = Number.isFinite(attestedAtMs)
  && attestedAtMs <= now.getTime() + maxFutureSkewMs
  && now.getTime() - attestedAtMs <= maxAttestationAgeMs;
const teamEmailAttested = teamEmailDesired
  && isSha256(attestationSha)
  && isSha256(attestationManifestSha)
  && attestationManifestSha === manifestSha
  && attestationFresh;

metadata.team_email_advertised = teamEmailAttested ? '1' : '0';
if (teamEmailAttested) {
  caps.push('team.email');
  metadata.workflow_attestation_sha = attestationSha;
  metadata.workflow_attestation_manifest_sha = attestationManifestSha;
  metadata.workflow_attested_at = new Date(attestedAtMs).toISOString();
} else if (teamEmailDesired) {
  metadata.team_email_attestation = 'missing_stale_or_manifest_mismatch';
}

const executor = String($env.VIRYAOS_EXECUTOR_ID || 'virya-n8n-primary').trim();
return [{ json: {
  executor_id: executor,
  version: 'viryaos-n8n-2026-08-14.1',
  manifest_sha: manifestSha,
  capabilities: caps.map(capability => ({ capability, version: 'v1' })),
  metadata,
  observed_at: now.toISOString(),
  expires_at: new Date(now.getTime() + 90 * 60 * 1000).toISOString(),
} }];

